const items = $input.all();
const data = items[0].json;

const title = data.title || 'Meeting Notes';
const notes = data.notes || '';
const attendees = data.attendees || [];
const channel = data.channel || '#general';
const date = data.date || new Date().toISOString().split('T')[0];
const actionItems = data.actionItems || [];

const internalAttendees = attendees.filter(a => !a.includes('@') || a.startsWith('U'));
const externalAttendees = attendees.filter(a => a.includes('@') && !a.startsWith('U'));

let slackMsg = `:memo: *${title}* — ${date}\n\n`;
slackMsg += `*Attendees:* ${attendees.join(', ')}\n\n`;
slackMsg += `*Notes:*\n${notes}\n\n`;

if (actionItems.length > 0) {
  slackMsg += '*Action Items:*\n';
  actionItems.forEach((item, i) => {
    slackMsg += `${i + 1}. ${item.task} — *Owner:* ${item.owner || 'TBD'} | *Due:* ${item.due || 'TBD'}\n`;
  });
}

return [{json: {
  title,
  notes,
  slackMsg,
  channel,
  date,
  internalAttendees,
  externalAttendees,
  actionItems,
  hasExternal: externalAttendees.length > 0
}}];

